@CsvSource({ "rwxrwxrwx,true,2", "rw-r--r--,false,3", "rw-------,true,4", "rw-rw----,false,5" })
public void testFilePermissionsAPI(final String filePermissions, final boolean createOnDemand, final int fileIndex) throws Exception {
    final File file = new File(DIR, "AppenderTest-" + fileIndex + ".log");
    final Path path = file.toPath();
    final Layout<String> layout = PatternLayout.newBuilder().withPattern(PatternLayout.SIMPLE_CONVERSION_PATTERN).build();
    // @formatter:off
    final FileAppender appender = FileAppender.newBuilder().withFileName(file.getAbsolutePath()).setName("test").withImmediateFlush(false).setIgnoreExceptions(false).withBufferedIo(false).withBufferSize(1).setLayout(layout).withCreateOnDemand(createOnDemand).withFilePermissions(filePermissions).build();
    // @formatter:on
    try {
        appender.start();
        assertTrue(appender.isStarted(), "Appender did not start");
        assertNotEquals(createOnDemand, Files.exists(path));
        long curLen = file.length();
        long prevLen = curLen;
        assertEquals(curLen, 0, "File length: " + curLen);
        for (int i = 0; i < 100; ++i) {
            final LogEvent event = //
            Log4jLogEvent.newBuilder().setLoggerName("TestLogger").setLoggerFqcn(FileAppenderPermissionsTest.class.getName()).setLevel(//
            Level.INFO).setMessage(new SimpleMessage("Test")).setThreadName(//
            this.getClass().getSimpleName()).setTimeMillis(System.currentTimeMillis()).build();
            try {
                appender.append(event);
                curLen = file.length();
                assertTrue(curLen > prevLen, "File length: " + curLen);
                // Give up control long enough for another thread/process to occasionally do something.
                Thread.sleep(25);
            } catch (final Exception ex) {
                throw ex;
            }
            prevLen = curLen;
        }
        assertEquals(filePermissions, PosixFilePermissions.toString(Files.getPosixFilePermissions(path)));
