        fos.write(bytes, 0, bytes.length);
        fos.flush();
    }
    assertEquals(bytes.length, file.length(), "all flushed to disk");
    try (final RandomAccessFileManager manager = RandomAccessFileManager.getFileManager(file.getAbsolutePath(), isAppend, true, RandomAccessFileManager.DEFAULT_BUFFER_SIZE, null, null, null)) {
