    assertEquals("Jumped the queue: test(2)+domain1(65)+domain2(61)=128: queue full", "Logging in toString() #127 (Log4j2 logged this message out of order to prevent deadlock caused by domain objects logging from their toString method when the async queue is full - LOG4J2-2031)", actual.pop());
