    final LogEvent event1 = //
    Log4jLogEvent.newBuilder().setLoggerName(this.getClass().getName()).setLoggerFqcn("org.apache.logging.log4j.core.layout.PatternSelectorTest$FauxLogger").setMarker(MarkerManager.getMarker("FLOW")).setLevel(//
    Level.TRACE).setIncludeLocation(true).setMessage(new SimpleMessage("entry")).build();
    final String result1 = new FauxLogger().formatEvent(event1, layout);
