@Test
void test_stack_trace_truncation() {
    // Create the exception to be logged.
    final Exception childError = new Exception("unique child exception message");
    final Exception parentError = new Exception("unique parent exception message", childError);
    // Create the event template.
    final String truncationSuffix = "~";
    final String eventTemplate = writeJson(asMap(// Raw exception.
    "ex", asMap("$resolver", "exception", "field", "stackTrace", "stackTrace", asMap("stringified", true)), // Exception matcher using strings.
    "stringMatchedEx", asMap("$resolver", "exception", "field", "stackTrace", "stackTrace", asMap("stringified", asMap("truncation", asMap("suffix", truncationSuffix, "pointMatcherStrings", Arrays.asList("this string shouldn't match with anything", parentError.getMessage()))))), // Exception matcher using regexes.
    "regexMatchedEx", asMap("$resolver", "exception", "field", "stackTrace", "stackTrace", asMap("stringified", asMap("truncation", asMap("suffix", truncationSuffix, "pointMatcherRegexes", Arrays.asList("this string shouldn't match with anything", parentError.getMessage().replace("unique", "[xu]n.que")))))), // Raw exception root cause.
    "rootEx", asMap("$resolver", "exceptionRootCause", "field", "stackTrace", "stackTrace", asMap("stringified", true)), // Exception root cause matcher using strings.
    "stringMatchedRootEx", asMap("$resolver", "exceptionRootCause", "field", "stackTrace", "stackTrace", asMap("stringified", asMap("truncation", asMap("suffix", truncationSuffix, "pointMatcherStrings", Arrays.asList("this string shouldn't match with anything", childError.getMessage()))))), // Exception root cause matcher using regexes.
    "regexMatchedRootEx", asMap("$resolver", "exceptionRootCause", "field", "stackTrace", "stackTrace", asMap("stringified", asMap("truncation", asMap("suffix", truncationSuffix, "pointMatcherRegexes", Arrays.asList("this string shouldn't match with anything", childError.getMessage().replace("unique", "[xu]n.que"))))))));
    // Create the layout.
    final JsonTemplateLayout layout = JsonTemplateLayout.newBuilder().setConfiguration(CONFIGURATION).setEventTemplate(eventTemplate).setStackTraceEnabled(true).build();
    // Create the log event.
    final LogEvent logEvent = Log4jLogEvent.newBuilder().setLoggerName(LOGGER_NAME).setThrown(parentError).build();
    // Check the serialized event.
    final String expectedMatchedExEnd = parentError.getMessage() + truncationSuffix;
    final String expectedMatchedRootExEnd = childError.getMessage() + truncationSuffix;
    usingSerializedLogEventAccessor(layout, logEvent, accessor -> {
        // Check the serialized exception.
        assertThat(accessor.getString("ex")).doesNotEndWith(expectedMatchedExEnd).doesNotEndWith(expectedMatchedRootExEnd);
        assertThat(accessor.getString("stringMatchedEx")).endsWith(expectedMatchedExEnd);
        assertThat(accessor.getString("regexMatchedEx")).endsWith(expectedMatchedExEnd);
        // Check the serialized exception root cause.
        assertThat(accessor.getString("rootEx")).doesNotEndWith(expectedMatchedExEnd).doesNotEndWith(expectedMatchedRootExEnd);
        assertThat(accessor.getString("stringMatchedRootEx")).endsWith(expectedMatchedRootExEnd);
        assertThat(accessor.getString("regexMatchedRootEx")).endsWith(expectedMatchedRootExEnd);
    });
}

