@Test
void epoch_nanos_should_not_overlap() {
    // Create the template.
    final Object eventTemplate = asMap("$resolver", "timestamp", "epoch", asMap("unit", "nanos"));
    // Create the logging context.
    withContextFromTemplate("TimestampResolverTest", eventTemplate, (loggerContext, appender) -> {
        // Log some.
        final Logger logger = loggerContext.getLogger(TimestampResolverTest.class);
        final int logEventCount = 5;
        for (int logEventIndex = 0; logEventIndex < logEventCount; logEventIndex++) {
            if (logEventIndex > 0) {
                uncheckedSleep(1);
            }
            logger.info("message #{}", logEventIndex);
        }
        // Read logged events.
        final List<Long> logEvents = appender.getData().stream().map(jsonBytes -> {
            final String json = new String(jsonBytes, StandardCharsets.UTF_8);
            return (long) readJson(json);
        }).collect(Collectors.toList());
        // Verify logged events.
        Assertions.assertThat(logEvents).hasSize(logEventCount).doesNotHaveDuplicates();
    });
}

@Test
@LoggerContextSource("threadLocalRecyclerNestedLogging.xml")
public void nested_logging_should_not_pollute_thread_local(final LoggerContext loggerContext, @Named(value = "List1") final ListAppender appender1, @Named(value = "List2") final ListAppender appender2) {
    final Logger logger = loggerContext.getLogger(ThreadLocalRecyclerNestedLoggingTest.class);
    logger.error("A", new ThrowableLoggingInGetMessage(logger));
    final List<String> messages1 = readAppendedMessages(appender1);
    final List<String> messages2 = readAppendedMessages(appender2);
    Assertions.assertThat(messages1).containsExactlyInAnyOrderElementsOf(messages2).containsExactlyInAnyOrderElementsOf(Stream.of("['B',null]", "['A','C']").map(json -> json.replaceAll("'", "\"")).collect(Collectors.toList()));
}

@ParameterizedTest
