@Test
void test_writeObject_Map() {
    final Map<String, Object> map = new LinkedHashMap<String, Object>() {

        {
            put("key1", "val1");
            put("key2", Collections.singletonMap("key2.1", "val2.1"));
            put("key3", Arrays.asList(3, (byte) 127, 4.5D, 4.6F, Arrays.asList(true, false), new BigDecimal("30.12345678901234567890123456789"), new BigInteger("12345678901234567890123456789"), Collections.singleton('a'), Collections.singletonMap("key3.3", "val3.3")));
            put("key4", new LinkedHashMap<String, Object>() {

                {
                    put("chars", new char[] { 'a', 'b', 'c' });
                    put("booleans", new boolean[] { true, false });
                    put("bytes", new byte[] { 1, 2 });
                    put("shorts", new short[] { 3, 4 });
                    put("ints", new int[] { 256, 257 });
                    put("longs", new long[] { 2147483648L, 2147483649L });
                    put("floats", new float[] { 1.0F, 1.1F });
                    put("doubles", new double[] { 2.0D, 2.1D });
                    put("objects", new Object[] { "foo", "bar" });
                }
            });
            put("key5\t", new Object() {

                @Override
                public String toString() {
                    return "custom-object\r";
                }
            });
            put("key6", Arrays.asList(new SortedArrayStringMap(new LinkedHashMap<String, Object>() {

                {
                    put("buzz", 1.2D);
                    put("foo", "bar");
                }
            }), new JdkMapAdapterStringMap(Collections.singletonMap("a", "b"))));
            put("key7", (StringBuilderFormattable) buffer -> buffer.append(7.7777777777777D));
        }
    };
    final String expectedJson = ("{" + "'key1':'val1'," + "'key2':{'key2.1':'val2.1'}," + "'key3':[" + "3," + "127," + "4.5," + "4.6," + "[true,false]," + "30.12345678901234567890123456789," + "12345678901234567890123456789," + "['a']," + "{'key3.3':'val3.3'}" + "]," + "'key4':{" + "'chars':['a','b','c']," + "'booleans':[true,false]," + "'bytes':[1,2]," + "'shorts':[3,4]," + "'ints':[256,257]," + "'longs':[2147483648,2147483649]," + "'floats':[1.0,1.1]," + "'doubles':[2.0,2.1]," + "'objects':['foo','bar']" + "}," + "'key5\\t':'custom-object\\r'," + "'key6':[{'buzz':1.2,'foo':'bar'},{'a':'b'}]," + "'key7':'7.7777777777777'" + "}").replace('\'', '"');
    final String actualJson = withLockedWriterReturning(writer -> writer.use(() -> writer.writeObject(map)));
    Assertions.assertThat(actualJson).isEqualTo(expectedJson);
}

